+    RuntimeCheck(1 <= rows && rows <= kMaxRows, "the front gather takes 1-", kMaxRows, " rows");
+    RuntimeCheck(
+        S.unwrap() % kVec == 0 && reinterpret_cast<uintptr_t>(slices.data_ptr()) % 16 == 0,
+        "front slices must be 16-byte aligned");
